public object VisitArrayLiteral(ArrayLiteralAst arrayLiteralAst)
{
    List<Expression> elementValues = new List<Expression>(arrayLiteralAst.Elements.Count);
    foreach (var element in arrayLiteralAst.Elements)
    {
        var elementValue = Compile(element);
        elementValues.Add(elementValue.Type != typeof(void) ? elementValue.Cast(typeof(object)) : Expression.Block(elementValue, ExpressionCache.AutomationNullConstant));
    }

    return Expression.NewArrayInit(typeof(object), elementValues);

    values ??= CaptureAstResults(subExpr, CaptureAstContext.Enumerable);

    if (pureExprAst is ArrayLiteralAst)
    {
        // If the pure expression is ArrayLiteralAst, just return the result.
        return values;
    }

    if (values.Type.IsPrimitive || values.Type == typeof(string))
    {
        // Slight optimization - no need for a dynamic site.  We could special case other
        // types as well, but it's probably not worth it.
        return Expression.NewArrayInit(typeof(object), values.Cast(typeof(object)));
    }

    if (values.Type == typeof(void))
    {
        // A dynamic site can't take void - but a void value is just an empty array.
        return Expression.Block(values, Expression.NewArrayInit(typeof(object)));
    }

    return DynamicExpression.Dynamic(PSToObjectArrayBinder.Get(), typeof(object[]), values);
}

public override DynamicMetaObject Bind(DynamicMetaObject target, DynamicMetaObject[] args)
{
    if (!target.HasValue)
    {
        return Defer(target, args);
    }

    if (target.Value == AutomationNull.Value)
    {
        return new DynamicMetaObject(Expression.Constant(Array.Empty<object>()),
            BindingRestrictions.GetInstanceRestriction(target.Expression, AutomationNull.Value)).WriteToDebugLog(this);
    }

    var enumerable = PSEnumerableBinder.IsEnumerable(target);
    if (enumerable == null)
    {
        return new DynamicMetaObject(
            Expression.NewArrayInit(typeof(object), target.Expression.Cast(typeof(object))),
            target.PSGetTypeRestriction()).WriteToDebugLog(this);
    }

    var value = PSObject.Base(target.Value);
    if (value is List<object>)
    {
        return new DynamicMetaObject(
            Expression.Call(PSEnumerableBinder.MaybeDebase(this, static e => e.Cast(typeof(List<object>)), target), CachedReflectionInfo.ObjectList_ToArray),
            PSEnumerableBinder.GetRestrictions(target)).WriteToDebugLog(this);
    }

    // It's enumerable, but not an List<object>.  Call EnumerableOps.ToArray
    return new DynamicMetaObject(
        Expression.Call(CachedReflectionInfo.EnumerableOps_ToArray, enumerable.Expression),
        target.PSGetTypeRestriction()).WriteToDebugLog(this);

private static object ConvertRelatedArrays(object valueToConvert,
                                           Type resultType,
                                           bool recursion,
                                           PSObject originalValueToConvert,
                                           IFormatProvider formatProvider,
                                           TypeTable backupTable)
{
    typeConversion.WriteLine("The element type of result is assignable from the element type of the value to convert");
    var originalAsArray = (Array)valueToConvert;
    var newValue = Array.CreateInstance(resultType.GetElementType(), originalAsArray.Length);
    originalAsArray.CopyTo(newValue, 0);
    return newValue;
}

private static object ConvertUnrelatedArrays(object valueToConvert,
                                             Type resultType,
                                             bool recursion,
                                             PSObject originalValueToConvert,
                                             IFormatProvider formatProvider,
                                             TypeTable backupTable)
{
    Array valueAsArray = valueToConvert as Array;
    Type resultElementType = resultType.GetElementType();
    Array resultArray = Array.CreateInstance(resultElementType, valueAsArray.Length);

    for (int i = 0; i < valueAsArray.Length; i++)
    {
        object resultElement = ConvertTo(valueAsArray.GetValue(i), resultElementType, false, formatProvider, backupTable);
        resultArray.SetValue(resultElement, i);
    }

    return resultArray;
}

private static object ConvertEnumerableToArray(object valueToConvert,
                                               Type resultType,
                                               bool recursion,
                                               PSObject originalValueToConvert,
                                               IFormatProvider formatProvider,
                                               TypeTable backupTable)
{
    try
    {
        ArrayList result = new ArrayList();
        Type resultElementType = resultType == typeof(Array) ? typeof(object) : resultType.GetElementType();
        typeConversion.WriteLine("Converting elements in the value to convert to the result's element type.");
        foreach (object obj in LanguagePrimitives.GetEnumerable(valueToConvert))
        {
            // false means no further recursions and therefore no cycles
            result.Add(ConvertTo(obj, resultElementType, false, formatProvider, backupTable));
        }

        return result.ToArray(resultElementType);
    }
    catch (Exception e)
    {
        typeConversion.WriteLine("Element conversion exception: \"{0}\".", e.Message);
        throw new PSInvalidCastException("InvalidCastExceptionEnumerableToArray", e,
            ExtendedTypeSystem.InvalidCastExceptionWithInnerException,
            valueToConvert.ToString(), resultType.ToString(), e.Message);

public object VisitCommandParameter(CommandParameterAst commandParameterAst)
{
    var arg = commandParameterAst.Argument;
    var errorPos = commandParameterAst.ErrorPosition;
    if (arg != null)
    {
        bool spaceAfterParameter = errorPos.EndLineNumber != arg.Extent.StartLineNumber ||
                                   errorPos.EndColumnNumber != arg.Extent.StartColumnNumber;
        return Expression.Call(
            CachedReflectionInfo.CommandParameterInternal_CreateParameterWithArgument,
            Expression.Constant(commandParameterAst),
            Expression.Constant(commandParameterAst.ParameterName),
            Expression.Constant(errorPos.Text),
            Expression.Constant(arg),
            Expression.Convert(GetCommandArgumentExpression(arg), typeof(object)),
            ExpressionCache.Constant(spaceAfterParameter),
            ExpressionCache.Constant(false));
    }

    return Expression.Call(
        CachedReflectionInfo.CommandParameterInternal_CreateParameter,
        Expression.Constant(commandParameterAst.ParameterName),
        Expression.Constant(errorPos.Text),
        Expression.Constant(commandParameterAst));

